READ_ONLY = {"search_docs", "get_order"}
NEEDS_APPROVAL = {"send_email", "issue_refund"}

def authorize(call, session) -> str:
    if call.name in READ_ONLY:
        return "allow"
    if call.name not in NEEDS_APPROVAL:
        return "deny"  # default-deny anything unknown
    if call.name == "issue_refund" and ____:
        return "deny"
    return "ask_human"
